"""A byte-preserving image download tutorial with a complete local fixture."""
import base64
import hashlib
from pathlib import Path

JAVASCRIPT = r'''const dataUrl = document.querySelector('#save-image-sample').value;
const prefix = 'data:image/png;base64,';
if (!dataUrl.startsWith(prefix)) throw new Error('Expected the PNG sample.');
const payload = dataUrl.slice(prefix.length).replace(/\s/g, '');
const binary = atob(payload);
const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
const signature = [137, 80, 78, 71, 13, 10, 26, 10];
if (!signature.every((value, i) => bytes[i] === value)) {
  throw new Error('The bytes do not have a PNG signature.');
}
const url = URL.createObjectURL(new Blob([bytes], { type: 'image/png' }));
const link = document.createElement('a');
link.href = url;
link.download = 'parsecove-example.png';
link.click();
setTimeout(() => URL.revokeObjectURL(url), 1000);'''

PYTHON = r'''import base64
from pathlib import Path

data_url = input("Paste the complete PNG sample data URL: ").strip()
prefix = "data:image/png;base64,"
if not data_url.startswith(prefix):
    raise ValueError("Expected the PNG sample.")
payload = "".join(data_url[len(prefix):].split())
image_bytes = base64.b64decode(payload, validate=True)
if base64.b64encode(image_bytes).decode("ascii") != payload:
    raise ValueError("Non-canonical Base64.")
if not image_bytes.startswith(b"\x89PNG\r\n\x1a\n"):
    raise ValueError("The bytes do not have a PNG signature.")
Path("parsecove-example.png").write_bytes(image_bytes)'''


def save_image_guide(code_example, faq, copy):
    image = (Path(__file__).parent / 'dist/assets/examples/sample.png').read_bytes()
    payload = base64.b64encode(image).decode('ascii')
    data_url = 'data:image/png;base64,' + payload
    digest = hashlib.sha256(image).hexdigest()
    head = '''<article class="guide-article"><header class="guide-header"><nav class="guide-breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/guides/">Guides</a><span>/</span><span aria-current="page">Save a Base64 image</span></nav><span class="eyebrow">IMAGES & FILES · WORKED GUIDE</span><h1>How to save a Base64 image to a file</h1><p class="guide-deck">Decode the image’s Base64 payload back to bytes, check its actual format, then download the original file. A complete PNG example below lets you follow the process from a data URL to a working image.</p><p class="guide-byline">By <a href="/about/">ParseCove</a> · Published <time datetime="2026-11-27">27 November 2026</time></p></header>
<nav class="guide-toc" aria-label="On this page"><strong>On this page</strong><a href="#save-steps">Save the image</a><a href="#complete-sample">Complete sample</a><a href="#data-url-parts">Data URL or raw Base64?</a><a href="#save-code">JavaScript & Python</a><a href="#image-errors">Troubleshooting</a><a href="#save-terms">Terms & FAQ</a></nav>
<section class="guide-section" id="save-steps"><h2>Save a Base64 image in four steps</h2><ol class="guide-steps"><li><strong>Get the complete value.</strong> Copy either the raw Base64 payload or the full <code>data:image/...;base64,</code> URL. Leave out surrounding JSON quotes, HTML markup and ellipses.</li><li><strong>Open the image converter.</strong> Paste the value into <a href="/base64-to-image/">Base64 to image</a> and press <strong>Preview image</strong>. The tool accepts PNG, JPEG, GIF and WebP image bytes.</li><li><strong>Check the preview and detected format.</strong> Confirm the dimensions and file type. If the declared media type disagrees with the bytes, the viewer explains the mismatch and uses the detected format for the download.</li><li><strong>Download the original image.</strong> Use <strong>Download original image</strong> and keep its detected extension. The download restores the encoded file bytes; it does not resize, recompress or convert image formats.</li></ol><p>The current viewer limits a file to 10 MB and a preview to 40 megapixels. A byte signature alone does not prove that a whole file is intact: the browser must also be able to decode it.</p></section>'''
    sample = f'''<section class="save-image-demo" id="complete-sample" aria-labelledby="save-sample-heading"><div><span class="eyebrow">TRY THE COMPLETE WORKFLOW</span><h2 id="save-sample-heading">A complete PNG sample</h2><p>This original ParseCove fixture is 320 × 180 pixels and contains {len(image):,} bytes. The text field contains its entire data URL, including the prefix and padding.</p></div><div class="save-sample-grid"><figure><img src="/assets/examples/sample.png" width="320" height="180" alt="ParseCove sample image with a blue background and geometric shapes"><figcaption>The original PNG, before Base64 encoding.</figcaption></figure><div><dl class="save-sample-facts"><div><dt>Format</dt><dd>image/png</dd></div><div><dt>Original file</dt><dd>{len(image):,} bytes</dd></div><div><dt>Base64 payload</dt><dd>{len(payload):,} characters</dd></div><div><dt>Complete data URL</dt><dd>{len(data_url):,} characters</dd></div></dl><p class="hint">The payload length is 4 × ceil(file bytes ÷ 3). The data URL also includes its media-type prefix.</p></div></div><label for="save-image-sample">Complete PNG data URL</label><textarea id="save-image-sample" class="mono" rows="4" readonly spellcheck="false">{data_url}</textarea><div class="actions">{copy('save-image-sample','Copy data URL')}<a class="button primary" id="save-open-viewer" href="/base64-to-image/?example=png">Open this example in the viewer</a><a class="button" id="save-original-png" href="/assets/examples/sample.png" download="parsecove-example.png">Download original PNG</a></div><details class="save-checksum"><summary>Check the original file’s SHA-256</summary><p>For this sample, compare the downloaded file with this complete checksum:</p><code id="save-image-sha">{digest}</code><p class="hint">This identifies the exact sample bytes. It is not a general safety or file-authenticity check.</p></details></section>'''
    parts = '''<section class="guide-section" id="data-url-parts"><h2>Data URL and raw Base64 are different inputs</h2><p>A Base64 image data URL contains a header and a payload separated by a comma. The header declares a media type and the <code>;base64</code> encoding flag. A raw Base64 string contains only the encoded bytes.</p>'''+code_example('Header layout — the complete sample is above', 'data:image/png;base64,')+'''<div class="table-wrap"><table><thead><tr><th>Part</th><th>Purpose</th><th>What to paste</th></tr></thead><tbody><tr><td><code>data:</code></td><td>Identifies a data URL</td><td>Keep it when using the full data URL.</td></tr><tr><td><code>image/png</code></td><td>Declares the media type</td><td>It describes the data; changing it does not change the bytes.</td></tr><tr><td><code>;base64,</code></td><td>Marks the encoding and ends the header</td><td>Keep the comma. A decoder expecting raw Base64 needs only the part after it.</td></tr><tr><td>Payload after the comma</td><td>Encodes the original file bytes</td><td>Copy the whole payload, including any final padding.</td></tr></tbody></table></div><p>Data URLs can also contain percent-encoded data without a Base64 flag. This tutorial and the image viewer cover the Base64 form. Raw Base64 is useful when an API asks for encoded file content without a data URL prefix.</p><p class="guide-source">References: <a href="https://developer.mozilla.org/en-US/docs/Web/URI/Reference/Schemes/data">MDN: data URLs</a> · <a href="https://www.rfc-editor.org/rfc/rfc2397">RFC 2397: the data URL scheme</a>.</p></section>'''
    code = '''<section class="guide-section" id="save-code"><h2>Save the sample with JavaScript or Python</h2><p>The examples below write the complete PNG sample without turning its binary bytes into UTF-8 text. They check the PNG signature; they are not full image-file validators. For unknown input, use the viewer’s format detection and browser preview as well.</p><div id="save-js-example">'''+code_example('JavaScript: run in this guide’s browser console', JAVASCRIPT)+'''</div><p><code>atob()</code> produces a binary string. Converting each character to a byte before constructing the Blob preserves the image bytes. Writing that binary string as ordinary UTF-8 text can change bytes above 127.</p><div id="save-python-example">'''+code_example('Python 3: run, then paste the copied sample at the prompt', PYTHON)+'''</div><p>The Python example writes a binary file with <code>write_bytes()</code>. Its strict decoder checks characters and padding; the round-trip check also rejects non-canonical trailing bits.</p><p class="guide-source">References: <a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/atob">MDN: atob and binary strings</a> · <a href="https://docs.python.org/3/library/base64.html">Python: Base64 decoding</a>.</p></section>'''
    html_snippet = '<img src="' + data_url + '" width="320" height="180" alt="ParseCove sample image">'
    embedding = '''<section class="guide-section" id="embed-image"><h2>Use the same data URL in an HTML image</h2><p>Put the complete data URL in an image element’s <code>src</code> attribute. The expandable example contains the entire sample, so you can copy it into an HTML document and preview it without a separate image URL.</p><details class="save-html-example"><summary>Show the complete HTML example</summary><div id="save-html-code">'''+code_example('HTML: the entire PNG is included', html_snippet)+'''</div></details><p>For your own file, <a href="/image-to-base64/">Image to Base64</a> can generate a full data URL, an HTML image tag or a CSS background declaration. The Base64 image viewer can then restore the same bytes.</p></section>'''
    errors = '''<section class="guide-section" id="image-errors"><h2>Why a Base64 image will not open</h2><p>For alphabet, padding or UTF-8 errors, use the <a href="/guides/fix-invalid-base64/">Base64 troubleshooting walkthrough</a> to separate encoding validation from interpreting the bytes.</p><div class="table-wrap"><table><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Invalid characters or padding</td><td>Copy the original value again. Remove only its surrounding markup, not arbitrary characters. A truncated payload cannot reliably be repaired by adding = signs.</td></tr><tr><td>Text decoder says the bytes are not UTF-8</td><td>Image bytes are binary. Use the image viewer rather than a Base64-to-text decoder.</td></tr><tr><td>The header says JPEG but the bytes are PNG</td><td>Use the format detected from the bytes. Renaming the file or editing the media type does not convert it.</td></tr><tr><td>The file starts like an image but preview fails</td><td>The image may be truncated or otherwise invalid. A correct opening signature is only one check.</td></tr><tr><td>An API returned - and _ characters</td><td>It may be Base64URL. Inspect it with the <a href="/base64url-decode/">Base64URL decoder</a> and copy the standard Base64 representation before using this image viewer.</td></tr></tbody></table></div><p>SVG and other image types are outside this viewer’s current preview support. A failure here does not mean every data URL or every browser supports the same formats.</p></section>'''
    terms = '''<section class="guide-section" id="save-terms"><h2>Terms used in this guide</h2><dl class="guide-terms"><div><dt>Data URL</dt><dd>A value beginning with <code>data:</code> that includes the content itself. Data URI is an older name often used for the same form.</dd></div><div><dt>Media type</dt><dd>A label such as <code>image/png</code> describing the intended content format. Also commonly called a MIME type.</dd></div><div><dt>Payload</dt><dd>The data after the comma. In a Base64 image data URL, it is the encoded image-file content.</dd></div><div><dt>File signature</dt><dd>Opening bytes associated with a format. A signature check helps identify a type but does not validate every part of a file.</dd></div></dl></section>'''
    questions = [
        ('Can I save the Base64 text directly as image.png?', 'Saving the encoded characters as a .png file does not restore the image. Decode the payload and write the resulting bytes. The filename extension alone does not change the content.'),
        ('Can Base64 decoding turn a PNG into JPEG?', 'No. Decoding restores the original encoded file bytes. Changing image formats requires decoding pixels and re-encoding them with an image editor or a format-conversion library.'),
        ('Should I copy the data URL or only its payload?', 'This image viewer accepts either. For another API or library, check its expected input. Many Base64 decoding functions want only the payload after the comma.'),
        ('Does every data URL use Base64?', 'No. The ;base64 flag is optional in the data URL syntax. Without it, the content can use percent encoding. The examples here deliberately use the Base64 image form.'),
    ]
    ending = '''<section class="guide-section guide-faq" id="save-faq"><h2>Common questions</h2>'''+''.join(faq(*item) for item in questions)+'''</section><section class="guide-next"><span class="eyebrow">USE THE WORKFLOW</span><h2>Preview the bytes, then save the image</h2><p>Use the viewer for Base64 input, or start with a file when you need to generate a data URL.</p><div class="actions"><a class="button primary" href="/base64-to-image/">Base64 to image</a><a class="button" href="/image-to-base64/">Image to Base64</a></div></section></article>'''
    return head + sample + parts + code + embedding + errors + terms + ending
